package com.contextgraph.controller; import com.contextgraph.dto.SearchDtos; import com.contextgraph.service.ContextSearchService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/search") public class SearchController{final ContextSearchService s;public SearchController(ContextSearchService s){this.s=s;}@GetMapping public List<SearchDtos.SearchResult>search(Authentication a,@RequestParam String q){return s.search(a.getName(),q);}@GetMapping("/understanding")public Map<String,String>understanding(@RequestParam String q){String x=q.toLowerCase();return Map.of("query",q,"topic",x.contains("internship")?"Internship":"General","time",x.contains("last month")?"Last month":x.contains("recent")?"Recent":"Any time","mode","Hybrid context retrieval");}}